 try{const records=await DL.list();if(generation!==designSaveGeneration||!$('save-design-dialog').open)return;const existing=records.find(r=>r.id===integrationState.designId);if(existing&&!librarySource&&existing.layout.design.revision===layout(false).design.revision)librarySource=DL.source(existing);const unknown=!!existing&&librarySource?.id!==existing.id;$('design-copy').checked=unknown;$('design-copy').disabled=unknown;$('design-save-note').textContent=unknown?'This drawing has no saved-version baseline. Save a new copy, or open the saved design to update it.':existing?'Saving updates the version opened in this window. Choose a new copy to keep that version.':'This saves a new design in your library.';$('design-copy-label').hidden=!existing;$('design-save-submit').textContent=unknown?'Save new copy':existing?'Update saved design':'Save design';$('design-save-submit').disabled=false;}catch(e){if(generation===designSaveGeneration&&$('save-design-dialog').open)$('design-save-error').textContent=e.message;}
