async function renderDesignLibrary(){
 const generation=++libraryRender,host=$('design-library');host.replaceChildren();$('design-library-status').textContent='Loading saved designs…';
 try{const records=await DL.list();if(generation!==libraryRender)return;const query=$('design-search').value.trim().toLowerCase(),shown=records.filter(r=>String(r.layout?.title||'').toLowerCase().includes(query));$('design-library-status').textContent=records.length?(shown.length+' of '+records.length+' saved designs'):'Your library is empty. Save the current design to start a collection.';
 for(const record of shown){const card=document.createElement('article');card.className='custom-card design-card';try{const raw=DL.prepare(record.layout,record.layout.title),preview=document.createElement('div');preview.className='design-thumbnail';if(raw.pieces.length)preview.innerHTML=I.picture(raw,{maxDimension:600}).svg;else preview.textContent='Empty design';card.append(preview);const name=document.createElement('h2');name.textContent=raw.title;card.append(name);const info=document.createElement('p');info.className='fine';const date=new Date(record.updatedAt);info.textContent=raw.pieces.length+' placed pieces · '+(raw.track.laneCount?raw.track.laneCount+' lanes · closed circuit':'Open / drawing-only layout')+(Number.isNaN(date.getTime())?'':' · Saved '+date.toLocaleString());card.append(info);const actions=document.createElement('div');actions.className='view-actions';const open=document.createElement('button');open.className='btn primary';open.textContent='Open in builder';open.onclick=async()=>{try{const fresh=await DL.get(record.id);confirmReplace(()=>{try{applyImport(fresh.layout,DL.source(fresh));}catch(e){say(e.message,true);}});}catch(e){say(e.message,true);}};const downloadButton=document.createElement('button');downloadButton.className='btn';downloadButton.textContent='Download JSON';downloadButton.onclick=async()=>{try{designDownload(await DL.get(record.id));}catch(e){say(e.message,true);}};const remove=document.createElement('button');remove.className='btn quiet';remove.textContent='Delete';remove.onclick=()=>{deleteDesignId=record.id;deleteDesignRevision=DL.source(record).revision;$('delete-design-name').textContent=raw.title;$('delete-design-dialog').showModal();};const exportButton=document.createElement('button');exportButton.className='btn';exportButton.textContent='Export…';exportButton.onclick=()=>{exportChoice='saved:'+record.id;location.hash='export';routeSection();};actions.append(open,exportButton,downloadButton,remove);card.append(actions);}catch(e){const error=document.createElement('p');error.textContent='A saved design could not be displayed: '+e.message;card.append(error);}host.append(card);}
 }catch(e){if(generation===libraryRender)$('design-library-status').textContent=e.message;}
}
function exportButtons(disabled){document.querySelectorAll('[data-track-export]').forEach(b=>b.disabled=disabled||b.hasAttribute('data-cad-export')&&!exportCadAvailable);}
function showExportTrack(model){
 exportCadAvailable=model.routed.sections>0;$('cad-export-note').textContent=exportCadAvailable?model.routed.sections+' routed sections available.'+(model.pieces.length>model.routed.sections?' Non-routed pieces are excluded.':''):'This track has no routed sections. Use PDF or PNG for a picture of modular track pieces.';
 $('export-summary').textContent=model.title+' · '+model.pieces.length+' placed pieces';$('export-source-note').textContent=exportChoice==='current'?'Current builder track, including changes not yet saved to the library.':'Saved library snapshot. Your current builder track is kept in place.';
 const preview=$('export-track-preview');preview.replaceChildren();if(model.pieces.length)preview.innerHTML=I.picture(model.layout,{maxDimension:500}).svg;else preview.textContent='This track is empty.';
 const notes=model.layout.compatibility.issues.map(issue=>issue.message);if(model.layout.timing.requiresLaneRemap)notes.unshift('Reconfirm lane mapping in SlotForge Timing.');$('timing-compatibility').textContent=notes.join(' ');$('export-contract').textContent='Integration contract '+model.layout.integration.contractVersion+'.';exportButtons(!model.pieces.length);
}
async function loadExportTrack(){
 const generation=++exportSourceGeneration;exportCadAvailable=false;exportButtons(true);$('export-source-error').textContent='';$('export-summary').textContent='Loading selected track…';$('export-track-preview').replaceChildren();
 try{const model=await XM.resolveSource(exportChoice,()=>layout(),DL.get);if(generation!==exportSourceGeneration)return;showExportTrack(model);}catch(e){if(generation!==exportSourceGeneration)return;$('export-summary').textContent='Selected track unavailable';$('export-source-note').textContent='Choose another track to export.';$('export-source-error').textContent=e.message;}
}
async function populateExportTracks(){
 const generation=++exportMenuGeneration,select=$('export-track-select');select.disabled=true;exportButtons(true);let records=[],libraryError='';
 try{records=await DL.list();}catch(e){libraryError=e.message;}if(generation!==exportMenuGeneration)return;select.replaceChildren();const current=document.createElement('option');current.value='current';current.textContent='Current builder track — '+title;select.append(current);
 if(records.length){const group=document.createElement('optgroup');group.label='Saved in Track Library';for(const record of records){const option=document.createElement('option');option.value='saved:'+record.id;option.textContent=String(record.layout?.title||'Unnamed saved track');const date=new Date(record.updatedAt);if(!Number.isNaN(date.getTime()))option.textContent+=' · '+date.toLocaleString();group.append(option);}select.append(group);}
 if(exportChoice!=='current'&&!records.some(r=>'saved:'+r.id===exportChoice)){const missing=document.createElement('option');missing.value=exportChoice;missing.textContent='Saved track unavailable — select another';select.append(missing);}select.value=exportChoice;select.disabled=false;await loadExportTrack();if(generation===exportMenuGeneration&&libraryError)$('export-source-error').textContent=libraryError;
}
async function exportSelectedTrack(format){
 const choice=exportChoice;exportButtons(true);try{const model=await XM.resolveSource(choice,()=>layout(),DL.get);if(choice!==exportChoice)return;if(!model.pieces.length)throw Error('Add pieces to this track before exporting.');showExportTrack(model);if(format==='pdf')openPdfReport(model.layout);else if(format==='slotforge')downloadTrack(model.layout);else if(format==='png')await exportPNG(model.layout);else if(format==='csv')exportCSV(model.layout);else if(format==='cad')cadUI.open(model.layout);}catch(e){$('export-source-error').textContent=e.message;say(e.message,true);}finally{if(choice===exportChoice)exportButtons(false);}
}
function routeSection(){
 const section=['custom','plugins','export','library','settings','routed','freeform'].includes(location.hash.slice(1))?location.hash.slice(1):'builder';
 finishDrag(true);stop();document.body.dataset.section=section;
 $('builder-view').hidden=section!=='builder';document.querySelector('.projectbar').hidden=section!=='builder';$('custom-view').hidden=section!=='custom';$('export-view').hidden=section!=='export';$('plugins-view').hidden=section!=='plugins';$('library-view').hidden=section!=='library';
 $('settings-view').hidden=section!=='settings';$('routed-view').hidden=section!=='routed';$('freeform-view').hidden=section!=='freeform';if(section==='freeform'&&freeformUI)freeformUI.enter();
 document.querySelectorAll('.sf-nav-link').forEach(a=>{if(a.dataset.section===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(section==='library')renderDesignLibrary();if(section==='custom'){renderPackControls();renderCustomLibrary();}if(section==='plugins')renderPlugins();
 if(section==='export'){renderPackControls();populateExportTracks();}
 if(section==='builder')requestAnimationFrame(()=>{updateView();renderCanvas();});
}
